// packages/core/src/obs/context.ts — owned by CORE. server imports this, never the reverse.
import { AsyncLocalStorage } from 'node:async_hooks';
import { randomBytes } from 'node:crypto';
import { trace } from '@opentelemetry/api';

export type ScopeKind = 'all' | 'group' | 'server' | 'smart';
export type Era = 'legacy' | 'modern';

/** Mutable in place. Exactly one writer per field, all inside the same run(). */
export interface RequestContext {
  /** 32 lowercase hex = a W3C trace-id. The ONLY correlation id in the system. */
  readonly requestId: string;
  readonly startedAt: number;          // performance.now()
  readonly era: Era;
  readonly protocolVersion: string;
  readonly transport: 'streamable-http' | 'stdio' | 'internal';
  /** set by the auth middleware, after run() has begun */
  principal: Principal | null;         // contract: owned by the auth subsystem
  scopeKind: ScopeKind;
  scope: string | null;                // group or server name
  /** UNTRUSTED, from _meta clientInfo. Capped 128, control chars stripped. */
  clientName: string | null;
  clientVersion: string | null;
  sourceIp: string | null;
  /** set by the engine when the call resolves to one upstream */
  server: string | null;
  upstreamMs: number | null;
}

const als = new AsyncLocalStorage<RequestContext>();

export function currentContext(): RequestContext | undefined { return als.getStore(); }
export function runWithContext<T>(ctx: RequestContext, fn: () => T): T { return als.run(ctx, fn); }
// .enterWith() is banned: eslint no-restricted-properties.

const TRACEPARENT = /^00-(?!0{32})([0-9a-f]{32})-[0-9a-f]{16}-[0-9a-f]{2}$/;

/** OTel on -> adopt the active span's traceId; else inbound traceparent if VALID; else fresh. */
export function newRequestId(inboundTraceparent?: string | null): string {
  const active = trace.getActiveSpan()?.spanContext().traceId;
  if (active && active !== '0'.repeat(32)) return active;
  const m = inboundTraceparent ? TRACEPARENT.exec(inboundTraceparent) : null;
  return m ? m[1] : randomBytes(16).toString('hex');
}

// packages/core/src/obs/log.ts
import pino from 'pino';

/** Closed set. Every log line carries one. This replaces free-text console.log. */
export type Evt =
  | 'boot.start' | 'boot.ready' | 'boot.shutdown'
  | 'mcp.request'            // one line per completed downstream request (the access log)
  | 'mcp.tool.call' | 'mcp.tool.denied' | 'mcp.tool.retry'
  | 'upstream.connect' | 'upstream.connected' | 'upstream.failed'
  | 'upstream.disconnected' | 'upstream.superseded' | 'upstream.stderr'
  | 'upstream.sleep' | 'upstream.wake'
  | 'auth.reject' | 'protocol.reject'
  | 'search.vector' | 'embed.sync'
  | 'audit.spill' | 'audit.payload.read'
  | 'db.migrate' | 'logs.dropped';

// A rendered line (NDJSON, one per line, stdout):
// {"level":"info","time":"2026-09-18T10:04:11.882Z","svc":"mcprouter","ver":"1.0.0",
//  "inst":"router-7c9","req":"4bf92f3577b34da6a3ce929d0e0e4736","usr":"u_31f",
//  "key":"ak_9a2","scope":"eng-tools","srv":"github","evt":"mcp.request",
//  "method":"tools/call","name":"create_issue","outcome":"ok","ms":812,"upstreamMs":790,
//  "inBytes":214,"outBytes":1880,"inHash":"9f1c2a7b4e0d88a1","msg":"tools/call ok"}

export const log = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  base: { svc: 'mcprouter', ver: VERSION, inst: process.env.HOSTNAME },
  timestamp: pino.stdTimeFunctions.isoTime,
  formatters: { level: (label) => ({ level: label }) },
  // AUTOMATIC correlation. No child-logger plumbing anywhere in core.
  mixin() {
    const c = currentContext();
    return c ? { req: c.requestId, usr: c.principal?.id, key: c.principal?.apiKeyId,
                 scope: c.scope, srv: c.server } : {};
  },
  // Mechanism #1: type-directed. Impossible to log a server config with values.
  serializers: {
    server: (s: ServerConfig) => ({ name: s.name, type: s.type, url: s.url,
      command: s.command, envKeys: Object.keys(s.env ?? {}), headerKeys: Object.keys(s.headers ?? {}) }),
    err: pino.stdSerializers.err,
  },
  // Mechanism #2: path-based, for the fixed HTTP surface only.
  redact: { censor: '[redacted]', paths: [
    '*.authorization', '*.Authorization', '*.cookie', '*.["x-api-key"]',
    '*.accessToken', '*.refreshToken', '*.clientSecret', '*.codeVerifier', '*.password',
  ]},
}, destination());  // multistream: stdout + ring (+ pino-roll when LOG_FILE)

// NEVER logged at any level: tool arguments, tool results, resource contents,
// prompt bodies, embedding query text. Those get inBytes/outBytes/inHash only.

// packages/core/src/obs/ring.ts
export interface LogRecord { level: string; time: string; evt?: string; req?: string;
  srv?: string; msg?: string; [k: string]: unknown }
export interface LogFilter { level?: number; evt?: string; srv?: string; req?: string; q?: string }

export class LogRing {
  private buf: LogRecord[]; private head = 0; private seq = 0;
  constructor(private cap = 2000) { this.buf = new Array(cap); }

  /** pino multistream destination. ponytail: JSON.parse per line; if sustained rate
   *  ever exceeds ~5k/s, store raw strings and prefilter with indexOf. */
  write(line: string): void { /* parse, store at head, head=(head+1)%cap, seq++ */ }

  /** Cursor-based read. A subscriber whose cursor fell off the end learns how many it missed. */
  since(cursor: number, f?: LogFilter): { records: LogRecord[]; cursor: number; dropped: number }
  query(f: LogFilter, limit = 500): LogRecord[]
  get cursor(): number { return this.seq; }
}
export const ring = new LogRing();

// packages/core/src/obs/metrics.ts — registry `reg`, prefix mcprouter_
// collectDefaultMetrics({ register: reg })  -> process_*, nodejs_* (event loop lag, GC, RSS)
// BUCKETS_FAST = [.01,.05,.1,.25,.5,1,2.5,5,10,30,60]
// BUCKETS_CONN = [.05,.1,.25,.5,1,2,5,10,30]
// BUCKETS_BYTES = [256,1e3,4e3,16e3,64e3,256e3,1e6,4e6]
//
// NAME                                            TYPE       LABELS                              CARDINALITY RISK
// mcprouter_build_info                            Gauge=1    version, commit, node_version        1. Static.
// mcprouter_upstream_state                        Gauge 0/1  server, transport, state             servers x 3 x 6. state in
//                                                                                                 {connected,connecting,disconnected,
//                                                                                                  oauth_required,sleeping,failed}.
//                                                                                                 server bounded by CONFIG. Safe.
// mcprouter_upstream_connect_attempts_total       Counter    server, outcome                      servers x 5 {success,refused,timeout,auth,protocol}.
// mcprouter_upstream_connect_duration_seconds     Histogram  server, outcome{success,failure}     servers x 2 x 9. Safe.
// mcprouter_upstream_last_success_ts_seconds      Gauge      server                               = servers. Alert on staleness w/o rate().
// mcprouter_upstream_tools_count                  Gauge      server                               = servers. Catches 'came back with 0 tools'.
// mcprouter_tool_calls_total                      Counter    server, tool, outcome                servers x tools x 5. THE TRAP: `tool` only
//                                                                                                 ever comes from a branded ResolvedTool;
//                                                                                                 unresolved -> tool="__unknown__" so client
//                                                                                                 input cannot mint series. outcome in
//                                                                                                 {ok,error,denied,unavailable,timeout}.
//                                                                                                 Exemplar: trace_id.
// mcprouter_client_calls_total                    Counter    client, outcome                      client = better-auth apiKey ID (admin-created,
//                                                                                                 bounded ~100) or 'session'/'anon'. NEVER the
//                                                                                                 client-supplied clientInfo.name. Kept SEPARATE
//                                                                                                 from tool_calls_total so the two medium
//                                                                                                 dimensions never multiply.
// mcprouter_tool_call_duration_seconds            Histogram  server, phase, outcome               servers x 2 x 2 x 12. NO `tool` label — that is
//                                                                                                 the 45k-series mistake. phase in {total,upstream};
//                                                                                                 total-upstream = OUR overhead. Exemplar: trace_id.
// mcprouter_tool_call_result_bytes                Histogram  server                               servers x 8. Finds the tool returning 3 MB.
// mcprouter_tool_calls_inflight                   Gauge      server                               = servers. Climbing inflight + flat completion
//                                                                                                 rate = hung upstream, visible in 5 seconds.
// mcprouter_tool_denied_total                     Counter    server, reason                       servers x 3 {disabled,not_in_group,no_scope}.
//                                                                                                 The CVE-class signal (mcphub afcc72f): a spike
//                                                                                                 means a client is calling what it cannot see.
// mcprouter_downstream_requests_total             Counter    route, method, code, era             ~8 routes x ~10 MCP methods x ~12 codes x 2.
//                                                                                                 route is the TEMPLATE (/mcp/:scope), never the
//                                                                                                 resolved path. ~2k worst case.
// mcprouter_downstream_request_duration_seconds   Histogram  route, method                        8 x 10 x 12. Safe.
// mcprouter_downstream_streams_active             Gauge      kind{request,listen}                 2. The modern-era replacement for sessions.
// mcprouter_sessions_active                       Gauge      transport                            1. LEGACY-ERA ONLY. Deleted when the SDK ships
//                                                                                                 2026-07-28 and Mcp-Session-Id is gone.
// mcprouter_auth_failures_total                   Counter    reason, surface                      5 x 2 {no_credential,bad_key,expired,
//                                                                                                 insufficient_scope,audience_mismatch} x {mcp,api}.
// mcprouter_protocol_errors_total                 Counter    code, era                            ~6 x 2. code in {-32020 HeaderMismatch,
//                                                                                                 -32022 UnsupportedProtocolVersion,-32600,-32601,
//                                                                                                 -32602,-32603}.
// mcprouter_context_tokens                        Gauge      scope_kind, scope, mode              (groups+servers+2) x 4 {gross,exposed,
//                                                                                                 smart_pd,smart_nopd}. ~1000 series at 200 srv +
//                                                                                                 50 groups. DELIBERATE: this is the Context Cost
//                                                                                                 differentiator on a graph. Ceiling ~2k series;
//                                                                                                 above that drop the `scope` label and keep SQL.
// mcprouter_embedding_sync_pending                Gauge      -                                    1.
// mcprouter_embedding_requests_total              Counter    provider, outcome                    4 x 2. provider from config.
// mcprouter_vector_search_duration_seconds        Histogram  scope_kind                           4 x 12. NOT by scope — query volume is unbounded.
// mcprouter_audit_queue_depth                     Gauge      -                                    1.
// mcprouter_audit_dropped_total                   Counter    -                                    1. Any nonzero = audit is lying. Page on it.
// mcprouter_audit_write_failures_total            Counter    -                                    1.
// mcprouter_db_pool_connections                   Gauge      state{total,idle,waiting}            3. One collect() reading pg Pool counters.
//                                                                                                 `waiting` rising = the #1 self-host outage.
// mcprouter_log_events_total                      Counter    level                                6. rate(...{level="error"}[5m]) gives error
//                                                                                                 alerting with NO log pipeline installed.
// mcprouter_log_stream_subscribers                Gauge      -                                    1. Hard cap 20.

// Typed recording surface — the branded type IS the cardinality enforcement:
export type ResolvedTool = { readonly __brand: 'ResolvedTool'; server: string; tool: string };
export function recordToolCall(ref: ResolvedTool | null, o: {
  outcome: 'ok'|'error'|'denied'|'unavailable'|'timeout';
  totalMs: number; upstreamMs?: number; outBytes?: number;
}): void;  // reads requestId from the ALS for the exemplar; ref===null => tool='__unknown__'

// packages/core/src/obs/otel.ts — depends on @opentelemetry/api ONLY (no-op when no SDK).
import { trace, SpanStatusCode, SpanKind, type Attributes } from '@opentelemetry/api';
const tracer = trace.getTracer('mcprouter');

export function withSpan<T>(name: SpanName, kind: SpanKind, attrs: Attributes,
                            fn: (setAttr: (a: Attributes) => void) => Promise<T>): Promise<T>;

export type SpanName =
  | 'mcp.request'           // SERVER, packages/server middleware. THE downstream span.
  | 'mcp.tool.call'         // INTERNAL, core. Resolve + filter + dispatch + retry.
  | 'mcp.upstream.call'     // CLIENT, core. The raw SDK client.callTool — its duration IS upstream_ms.
  | 'mcp.upstream.connect'  // CLIENT, core. Transport create + handshake.
  | 'mcp.upstream.list'     // CLIENT, core. tools/prompts/resources listing after connect.
  | 'mcp.search.vector'     // INTERNAL, core. pgvector cosine query.
  | 'mcp.embed';            // CLIENT, core. Embedding provider call.

// Attributes, by span. NEVER a tool argument, result, resource body or query text.
// mcp.request:          mcp.method, mcp.name, mcp.scope.kind, mcp.scope, mcp.era,
//                       mcp.protocol_version, mcprouter.principal.kind, mcprouter.api_key.id,
//                       mcp.client.name, mcp.client.version, http.response.status_code
// mcp.tool.call:        mcp.server, mcp.tool, mcp.tool.namespaced, mcp.outcome,
//                       mcp.input.bytes, mcp.output.bytes, mcp.retried (bool)
// mcp.upstream.call:    mcp.server, mcp.transport, server.address, mcp.outcome
// mcp.upstream.connect: mcp.server, mcp.transport, mcp.protocol_version, mcp.outcome,
//                       mcprouter.generation  <- the generation counter, so a superseded
//                                                connect is VISIBLE in the trace rather than
//                                                a mystery in the logs
// mcp.upstream.list:    mcp.server, mcp.capability{tools|prompts|resources}, mcp.item_count
// mcp.search.vector:    mcprouter.scope.kind, mcprouter.query.len, mcprouter.k,
//                       mcprouter.threshold, mcprouter.hits
// mcp.embed:            mcprouter.embed.provider, mcprouter.embed.model,
//                       mcprouter.embed.batch, mcprouter.embed.dims
// DB spans come free from @opentelemetry/instrumentation-pg. HTTP server/client spans come
// free from instrumentation-http + instrumentation-undici.

// packages/core/src/db/schema/audit.ts
import { pgTable, bigserial, timestamp, text, integer, char, jsonb, inet, index } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

export const auditEvent = pgTable('audit_event', {
  id:            bigserial('id', { mode: 'bigint' }).primaryKey(),
  at:            timestamp('at', { withTimezone: true }).notNull().defaultNow(),
  requestId:     char('request_id', { length: 32 }).notNull(),      // == trace id
  principalKind: text('principal_kind').notNull(),                  // user|api_key|oauth_client|system
  principalId:   text('principal_id'),
  apiKeyId:      text('api_key_id'),
  clientName:    text('client_name'),                              // UNTRUSTED, capped 128
  clientVersion: text('client_version'),                           // UNTRUSTED, capped 64
  sourceIp:      inet('source_ip'),
  scopeKind:     text('scope_kind').notNull(),                     // all|group|server|smart
  scope:         text('scope'),
  server:        text('server'),                                   // null for meta-tools
  method:        text('method').notNull(),                         // tools/call|tools/list|resources/read|...
  name:          text('name'),                                     // UNPREFIXED tool/resource/prompt name
  outcome:       text('outcome').notNull(),                        // ok|error|denied|unavailable|timeout
  errorCode:     integer('error_code'),                            // JSON-RPC code
  errorMessage:  text('error_message'),                            // capped 512
  durationMs:    integer('duration_ms').notNull(),
  upstreamMs:    integer('upstream_ms'),
  inputBytes:    integer('input_bytes'),
  outputBytes:   integer('output_bytes'),
  inputHash:     char('input_hash', { length: 16 }),               // sha256 prefix, canonical JSON
  inputKeys:     text('input_keys').array(),                       // 'metadata' mode: KEY NAMES only
  input:         jsonb('input'),                                   // 'full' mode only, <=64 KB
  output:        jsonb('output'),                                  // 'full' mode only, <=64 KB
  credentialed:  sql`boolean`,                                     // per-user credential -> metadata forced
}, (t) => [
  index('audit_at_idx').on(t.at.desc()),
  index('audit_server_at_idx').on(t.server, t.at.desc()),
  index('audit_req_idx').on(t.requestId),
  index('audit_principal_at_idx').on(t.principalId, t.at.desc()),
  // partial: the error feed and the triage screen both start here
  index('audit_err_idx').on(t.at.desc()).where(sql`outcome <> 'ok'`),
]);

// Retention (daily timer, packages/core/src/obs/retention.ts):
//   UPDATE audit_event SET input=NULL, output=NULL
//     WHERE at < now() - $payloadDays * interval '1 day' AND (input IS NOT NULL OR output IS NOT NULL);
//   DELETE FROM audit_event WHERE id IN (
//     SELECT id FROM audit_event WHERE at < now() - $retentionDays * interval '1 day' LIMIT 10000);
//   -- looped until 0 rows. ponytail: plain batched DELETE; switch to monthly RANGE
//   -- partitions + DROP PARTITION above ~50M rows.

// packages/server/src/obs/routes/*.ts  (Hono)
GET  /healthz                       // liveness. UNAUTH. 200 {"status":"ok"} always, unless the
                                    // loop is wedged. Touches no dependency. No body detail.
GET  /readyz                        // readiness. UNAUTH. 200 {"status":"ready"} | 503
                                    // {"status":"not_ready","checks":{"migrations":true,"db":false,
                                    //  "registry":true,"routes":true}}
                                    // Booleans only — NO server names, NO version string.
                                    // Upstream MCP health is deliberately EXCLUDED.
GET  /metrics                       // prom-client. Requires apiKey permission metrics:read OR an
                                    // admin session. OpenMetrics content-type when Accept asks.
GET  /api/health/fleet              // AUTH. Always 200. A report, never a probe.
                                    // {summary:{total,connected,degraded,failed,sleeping},
                                    //  servers:[{name,transport,state,since,lastError,lastSuccessAt,
                                    //            toolCount,p95Ms,errorRate5m}]}
GET  /api/logs?level&evt&srv&req&q&limit        // AUTH admin. Ring query, <=500.
GET  /api/logs/stream?level&evt&srv&req         // AUTH admin, SESSION COOKIE ONLY (never ?token=).
                                    // SSE. Cache-Control: no-store, X-Accel-Buffering: no,
                                    // ':\r\n' keep-alive every 15 s. Max 20 concurrent subscribers.
GET  /api/observability/triage?window=15m       // AUTH. THE one-screen answer. One SQL query.
GET  /api/observability/audit?server&principal&outcome&from&to&cursor  // AUTH audit:read. Metadata only.
GET  /api/observability/audit/:id/payload      // AUTH audit:payload:read. Admin only.
                                    // Writes its own audit row (evt audit.payload.read) on every hit.
GET  /api/observability/request/:requestId     // AUTH. {audit, logs:LogRecord[], traceUrl|null}
                                    // traceUrl = OTEL_TRACE_URL_TEMPLATE with {traceId} substituted.

// FROM packages/server (HTTP/transport subsystem):
//   - outermost middleware order is FIXED: (1) start mcp.request span, (2) newRequestId(),
//     (3) runWithContext(ctx, next). Auth runs INSIDE (3) and sets ctx.principal.
//   - set response header x-request-id: ctx.requestId, on every response incl. errors.
//   - include error.data.requestId in every JSON-RPC error body.
//   - call obs.recordDownstream({ route, method, code, era, ms }) on response.
//
// FROM packages/core engine (routing/aggregation subsystem):
export interface EngineObsHooks {
  onToolCall(ref: ResolvedTool | null, r: {
    outcome: 'ok'|'error'|'denied'|'unavailable'|'timeout';
    deniedReason?: 'disabled'|'not_in_group'|'no_scope';
    totalMs: number; upstreamMs?: number;
    inputBytes: number; outputBytes: number;
    inputKeys: string[]; inputHash: string;
    input?: unknown; output?: unknown;   // passed ONLY when policy === 'full'
    credentialed: boolean;               // true => policy forced to 'metadata'
    errorCode?: number; errorMessage?: string;
  }): void;
  onUpstreamState(server: string, state: UpstreamState, generation: number, err?: Error): void;
  onUpstreamConnect(server: string, transport: string, ms: number, outcome: string): void;
  onContextTokens(scopeKind: ScopeKind, scope: string,
                  mode: 'gross'|'exposed'|'smart_pd'|'smart_nopd', tokens: number): void;
  onVectorSearch(scopeKind: ScopeKind, ms: number, hits: number): void;
}
// The engine MUST report `denied` vs `unavailable` internally even though the WIRE
// response for both is byte-identical (mcphub's ToolUnavailableError contract,
// mcpService.ts:2654). Observability keeps the distinction the protocol hides.
//
// FROM the auth subsystem: Principal { kind, id, apiKeyId?, displayName }; better-auth apiKey
//   `permissions` must define metrics:read, audit:read, audit:payload:read; the session cookie
//   must be HttpOnly + SameSite=Lax so EventSource can authenticate without a query token.
// FROM the db subsystem: the drizzle instance, the pg Pool (for the pool gauges), and the
//   migration runner's applied-state (for /readyz).
// FROM the registry subsystem: the first-reconciliation-complete flag (for /readyz).

// packages/web/src/features/observability/useLogStream.ts
export function useLogStream(f: LogFilter): { records: LogRecord[]; dropped: number;
                                              connected: boolean; pause(): void; resume(): void };
// ONE EventSource('/api/logs/stream?' + qs) — cookie auth, no token in the URL.
// Server-side filtering (level/evt/srv/req/q) so a per-server view is not a client-side
// firehose. Records held in a fixed 2000-slot array (same cap as the ring) so the tab
// cannot OOM. Backoff 1s -> 8s on disconnect. Auto-pause on scroll-up.

// TriagePanel: TanStack Query useQuery(['triage', window], 15s refetch) + one Prometheus
//   range query per visible row for the sparkline. Columns:
//   server | state dot | calls | err% | p50 | p95 (sparkline) | overhead | top caller | callers
//   Sorted by p95 desc. Row click -> by-caller breakdown. Cell click -> RequestDrawer.

// RequestDrawer({ requestId }): GET /api/observability/request/:id ->
//   the audit row, every log line with that req in time order, and the trace deep link.
//   The requestId renders as a mono chip with a copy button everywhere it appears.

// a11y baseline (non-negotiable): the log stream is role="log" aria-live="polite"
// aria-relevant="additions"; status dots carry a visible text label, never colour or an
// emoji alone; the triage table is a real <table> with <caption> and scope="col";
// pause/resume is a <button aria-pressed>; drawer is a focus-trapped <dialog>.
